import * as THREE from 'three/webgpu';
import { texture as tsTexture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture
  const imageUrl = config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png';
  const map = ctx.textureLoader.load(imageUrl);

  // Configure texture properties
  map.colorSpace = THREE.SRGBColorSpace;
  map.minFilter = THREE.LinearFilter;
  map.magFilter = THREE.LinearFilter;

  // Create plane geometry with 1.6:1 aspect ratio (512:320 from atlas)
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Create material using TSL
  const mapNode = tsTexture(map);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: mapNode,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement
  const pos = config.scenePosition || { x: 0, y: -0.3, z: 0 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };

  mesh.position.set(pos.x, pos.y, pos.z);
  mesh.rotation.order = 'XYZ';
  mesh.rotation.set(rot.x, rot.y, rot.z);
  mesh.scale.set(scl.x, scl.y, scl.z);

  group.add(mesh);

  // Initialize event handlers
  group.userData.handlers = {};

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return group;
}
